import esbuild from 'esbuild';
import process from 'process';

const production = process.argv[2] === 'production';

const banner = `/*
 * Othoughts
 * This file is generated by esbuild. The source lives in src/ in the plugin's repository.
 */`;

const context = await esbuild.context({
	banner: { js: banner },
	entryPoints: ['src/main.js'],
	bundle: true,
	external: ['obsidian', 'electron'],
	format: 'cjs',
	target: 'es2018',
	charset: 'utf8',
	logLevel: 'info',
	sourcemap: production ? false : 'inline',
	treeShaking: true,
	minify: false, // readable output: what ships is what you can audit
	outfile: 'main.js',
});

if (production) {
	await context.rebuild();
	process.exit(0);
} else {
	await context.watch();
}
